from django.utils import timezone


def _add_months(moment, months):
    month_index = moment.month - 1 + months
    year = moment.year + month_index // 12
    month = month_index % 12 + 1
    return moment.replace(year=year, month=month, day=min(moment.day, calendar.monthrange(year, month)[1]))


def backfill_lots_and_cost(apps, schema_editor):
    """
    Points held before expiry existed become one lot per wallet, dated a full
    default period from now, so nobody loses points the day this ships. A
    product creation cost below 1 goes back to the default: products are
    never free.
    """
    now = timezone.now()
    expires_at = _add_months(now, getattr(django_settings, "POINT_EXPIRY_MONTHS", 2))
    for wallet_model, lot_model in (
        ("SellerWallet", "SellerPointLot"),
        ("StaffWallet", "StaffPointLot"),
    ):
        Wallet = apps.get_model("points", wallet_model)
        Lot = apps.get_model("points", lot_model)
        Lot.objects.bulk_create(
            Lot(wallet=wallet, amount=wallet.balance, remaining=wallet.balance,
                received_at=now, expires_at=expires_at)
            for wallet in Wallet.objects.filter(balance__gt=0)
        )

    ProductCreationCost = apps.get_model("points", "ProductCreationCost")
    ProductCreationCost.objects.filter(required_points__lt=1).update(
        required_points=getattr(django_settings, "PRODUCT_CREATION_POINT_COST", 5)
    )


